 {cmd:`sha256sum ${log} ${authority} 2>/dev/null; stat -c '%y %s %n' ${log} ${authority} 2>/dev/null`,workdir:wd,yield_time_ms:10000,max_output_tokens:8000,description:"Record supplied log and authority baseline identity"}
];
